static RAMFN int fl_erase4k_ram(uint32_t off, uint32_t *took_us)
{
    fl_saved_t s; int rc;
    if (!FL_ERASE_GUARD(off, 0x1000u) || (off & 0xFFFu))
        return -1;
    if (fl_enter(&s)) return -2;
    fl_wren();
    if (!(fl_rdsr(0x05) & 2u)) rc = -3;           /* WEL did not set */
    else {
        fl_cs(0); fl_tx(0x20); fl_addr(off); fl_cs(1);
        fl_inval(off, 4096u);
        rc = fl_wait_ready(500000u, took_us);     /* generic NOR max 400 ms */
    }
    fl_exit(&s);
    return rc;
}

static RAMFN int fl_read_ram(uint32_t off, uint8_t *dst, uint32_t n)   /* 0x0B fast read */
{
    fl_saved_t s; uint32_t i;
    if (fl_enter(&s)) return -2;
    fl_cs(0); fl_tx(0x0B); fl_addr(off); fl_tx(0xFF);
    for (i = 0; i < n; i++) dst[i] = fl_rx();
    fl_cs(1);
    fl_exit(&s);
    return 0;
}

int sm_rows(const uint16_t *px, unsigned left, unsigned top, unsigned width, unsigned rows)
{
    unsigned before = sm_length;
    for (unsigned row = 0; row < rows; ++row, px += width)
        for (unsigned i = 0; i < width;) {
            if (sm_length + 1u + SM_MESSAGE > SM_BUFFER) { /* room for a whole message, or wait */
                if (!before) return 1; /* bigger than the whole buffer: sent as far as it fits */
                sm_length = before;
                return 0;
            }
            uint8_t *out = sm_buffer + sm_length;
            unsigned y = top + row, x = left + i, k = 10;
            out[1] = 0xf0; out[2] = 0x7d; out[3] = 'F'; out[4] = 'S'; out[5] = 1;
            out[6] = (uint8_t)(y & 127u); out[7] = (uint8_t)(y >> 7);
            out[8] = (uint8_t)(x & 127u); out[9] = (uint8_t)(x >> 7);
            for (; i < width && k + 5u <= SM_MESSAGE; k += 4) {
                unsigned run = 1, c = px[i];
                while (i + run < width && run < 127 && px[i + run] == c) ++run;
                out[k] = (uint8_t)run;
                out[k + 1] = (uint8_t)(c & 127u);
                out[k + 2] = (uint8_t)((c >> 7) & 127u);
                out[k + 3] = (uint8_t)(c >> 14);
                i += run;
            }
            out[k] = 0xf7;
            out[0] = (uint8_t)k;
            sm_length += 1u + k;
        }
    return 1;
}

static uint8_t fm1__p33_xfer(uint8_t b)
{
    uint32_t n = 100000u;
    FM1_P33_DAT = b;
    FM1_P33_CON |= 1u << 4;
    (void)FM1_P33_CON;                           /* stands in for csync */
    while (FM1_P33_CON & (1u << 1))
        if (--n == 0) {
            fm1_p33_timeouts++;
            break;
        }
    return (uint8_t)FM1_P33_DAT;
}

int plat_midi_in(uint32_t *pkt, int *port)       /* the script's "midi" */
{
    int p;
    if (mi_r == mi_w)
        return 0;
    p = (int)min_port[mi_r % MQ];
    if (port)
        *port = p;
    *pkt = min_q[mi_r++ % MQ];
    if (p >= 0 && p < NPORTS)
        midi_counted(p, 0, *pkt);
    return 1;
}

/* the current copy: the valid one with the highest seq (A on a tie), -1 when
 * neither is valid. Headers first, so only the winner's payload is read (it
 * is left in st_buf); *h gets its header. */
static int st_current(uint32_t obj, st_hdr_t *h)
{
    st_hdr_t a, b;
    int va = st_head(obj, 0, &a) == 0, vb = st_head(obj, 1, &b) == 0;
    if (vb && (!va || b.seq > a.seq)) {
        if (st_body(obj, 1, &b) == 0) {
            *h = b;
            return 1;
        }
        vb = 0;
    }
    if (va && st_body(obj, 0, &a) == 0) {
        *h = a;
        return 0;
    }
    if (vb && st_body(obj, 1, &b) == 0) {
        *h = b;
        return 1;
    }
    return -1;
}

void touch_poll(void)
{
    touch_ev_t e;
    while (touch_take(&e)) {
        if (e.type == TOUCH_PRESS) {
            touch_held |= 1u << e.key;
            touch_v[e.key] = e.vel;
        } else {
            touch_held &= ~(1u << e.key);
        }
    }
    touch_update();
}

