/* a thick polyline (each segment a quad) */
static void mask_line(const float *p, int n, float width)
{
    int i;
    for (i = 0; i + 1 < n; i++) {
        float dx = p[2 * i + 2] - p[2 * i], dy = p[2 * i + 3] - p[2 * i + 1], l = dx * dx + dy * dy, q[8], k;
        if (l < 1e-6f)
            continue;
        k = 0.5f * width / esqrt(l);
        q[0] = p[2 * i] - dy * k + 0.5f;
        q[1] = p[2 * i + 1] + dx * k + 0.5f;
        q[2] = p[2 * i + 2] - dy * k + 0.5f;
        q[3] = p[2 * i + 3] + dx * k + 0.5f;
        q[4] = p[2 * i + 2] + dy * k + 0.5f;
        q[5] = p[2 * i + 3] - dx * k + 0.5f;
        q[6] = p[2 * i] + dy * k + 0.5f;
        q[7] = p[2 * i + 1] - dx * k + 0.5f;
        mask_poly(q, 4);
    }
}

/* a frequency: "800 Hz", "1.1 kHz" */
static void hz_text(char *b, int hz)
{
    char t[8];
    b[0] = 0;
    if (hz < 1000) {
        itoa_s(hz, t);
        cat_s(b, t);
        cat_s(b, " Hz");
    } else {
        int d = (hz + 50) / 100;
        itoa_s(d / 10, t);
        cat_s(b, t);
        cat_s(b, ".");
        itoa_s(d % 10, t);
        cat_s(b, t);
        cat_s(b, " kHz");
    }
}

static int um_put(uint32_t pkt)                    /* into midi_in_q (usb.c): 0 = full */
{
    if (mi_w - mi_r >= MQ)
        return 0;
    midi_in_q[mi_w % MQ] = pkt | 0x10u;           /* cable 1: from the jack */
    RING_PUBLISH();
    mi_w++;
    return 1;
}

static uint32_t ota_crc16(const uint8_t *p, uint32_t n, uint32_t c)   /* poly 0x1021, init 0 */
{
    uint32_t i;
    while (n--) {
        c ^= (uint32_t)*p++ << 8;
        for (i = 0; i < 8u; i++)
            c = c & 0x8000u ? (c << 1) ^ 0x1021u : c << 1;
        c &= 0xFFFFu;
    }
    return c;
}

void erk_soft(int val)
{
